struct SegmentTree {
    int n;
    vector<int> cnt, len;
    SegmentTree(int size) {
        n = size;
        cnt.assign(4 * n, 0);
        len.assign(4 * n, 0);
    }
    void update(int idx, int l, int r, int ql, int qr, int val, const vector<int> &ys) {
        if (ql >= r || qr <= l) return;
        if (ql <= l && r <= qr) {
            cnt[idx] += val;
        } else {
            int mid = (l + r) / 2;
            update(idx*2, l, mid, ql, qr, val, ys);
            update(idx*2+1, mid, r, ql, qr, val, ys);
        }
        if (cnt[idx] > 0) {
            len[idx] = ys[r] - ys[l];
        } else if (r - l == 1) {
            len[idx] = 0;
        } else {
            len[idx] = len[idx*2] + len[idx*2+1];
        }
    }
    int total() { return len[1]; }
};

