using namespace std;

struct Event {
    int x, y1, y2, type; // type: +1 add, -1 remove
    bool operator<(const Event& other) const {
        return x < other.x;
    }
};

struct SegTree {
    struct Node {
        int cover = 0;
        int len = 0;      // total covered length
        int cnt = 0;      // number of disjoint covered segments
        bool lcov = false, rcov = false;
    };

    int n;
    vector<Node> st;
    vector<int> ys;

    SegTree(const vector<int>& _ys) : ys(_ys) {
        n = (int)ys.size() - 1; // number of elementary intervals
        st.resize(max(1, 4 * n));
    }

    void pull(int p, int l, int r) {
        if (st[p].cover > 0) {
            st[p].len = ys[r + 1] - ys[l];
            st[p].cnt = 1;
            st[p].lcov = st[p].rcov = true;
        } else if (l == r) {
            st[p].len = 0;
            st[p].cnt = 0;
            st[p].lcov = st[p].rcov = false;
        } else {
            const Node &L = st[p << 1], &R = st[p << 1 | 1];
            st[p].len = L.len + R.len;
            st[p].cnt = L.cnt + R.cnt - (L.rcov && R.lcov ? 1 : 0);
            st[p].lcov = L.lcov;
            st[p].rcov = R.rcov;
        }
    }

    void update(int p, int l, int r, int ql, int qr, int val) {
        if (ql > r || qr < l || ql > qr) return;
        if (ql <= l && r <= qr) {
            st[p].cover += val;
            pull(p, l, r);
            return;
        }
        int m = (l + r) >> 1;
        update(p << 1, l, m, ql, qr, val);
        update(p << 1 | 1, m + 1, r, ql, qr, val);
        pull(p, l, r);
    }

    void update(int ql, int qr, int val) {
        if (n <= 0 || ql > qr) return;
        update(1, 0, n - 1, ql, qr, val);
    }

    int coveredLen() const {
        return n > 0 ? st[1].len : 0;
    }

    int segmentCount() const {
        return n > 0 ? st[1].cnt : 0;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, r;
    cin >> n >> r;

    vector<array<int, 4>> rects;
    rects.reserve(n);
    vector<int> ys;
    ys.reserve(2 * n);

    for (int i = 0; i < n; ++i) {
        int x1, y1, x2, y2;
        cin >> x1 >> y1 >> x2 >> y2;
        if (x1 == x2 || y1 == y2) continue; // ignore degenerate rectangles
        if (x1 > x2) swap(x1, x2);
        if (y1 > y2) swap(y1, y2);
        rects.push_back({x1, y1, x2, y2});
        ys.push_back(y1);
        ys.push_back(y2);
    }

    if (rects.empty()) {
        cout << 0 << '\n';
        if (r == 2) cout << 0 << '\n';
        return 0;
    }

    sort(ys.begin(), ys.end());
    ys.erase(unique(ys.begin(), ys.end()), ys.end());

    vector<Event> events;
    events.reserve(rects.size() * 2);

    for (auto &rec : rects) {
        int x1 = rec[0], y1 = rec[1], x2 = rec[2], y2 = rec[3];
        int l = lower_bound(ys.begin(), ys.end(), y1) - ys.begin();
        int rr = lower_bound(ys.begin(), ys.end(), y2) - ys.begin();
        // cover elementary intervals [l, rr-1]
        events.push_back({x1, l, rr - 1, +1});
        events.push_back({x2, l, rr - 1, -1});
    }

    sort(events.begin(), events.end());

    SegTree st(ys);

    long long area = 0;
    long long perimeter = 0;

    int prevX = events[0].x;
    int i = 0, m = events.size();

    while (i < m) {
        int x = events[i].x;
        long long dx = (long long)x - prevX;

        long long coverLenBefore = st.coveredLen();
        long long segCntBefore = st.segmentCount();

        area += coverLenBefore * dx;
        if (r == 2) {
            perimeter += 2LL * segCntBefore * dx; // horizontal parts
        }

        long long before = st.coveredLen();
        while (i < m && events[i].x == x) {
            st.update(events[i].y1, events[i].y2, events[i].type);
            ++i;
        }
        long long after = st.coveredLen();

        if (r == 2) {
            perimeter += llabs(after - before); // vertical parts at x
        }

        prevX = x;
    }

    cout << area << '\n';
    if (r == 2) cout << perimeter << '\n';

    return 0;
}

