    covered = [bytearray(MAXC) for _ in range(MAXC)]

    for _ in range(n):
        x1 = int(next(it))
        y1 = int(next(it))
        x2 = int(next(it))
        y2 = int(next(it))
        for y in range(y1, y2):
            covered[y][x1:x2] = b'\x01' * (x2 - x1)

    area = 0
    perimeter = 0

    for y in range(MAXC):
        row = covered[y]
        prev_row = covered[y - 1] if y > 0 else None
        next_row = covered[y + 1] if y + 1 < MAXC else None

        for x in range(MAXC):
            if row[x]:
                area += 1
                if x == 0 or not row[x - 1]:
                    perimeter += 1
                if x == MAXC - 1 or not row[x + 1]:
                    perimeter += 1
                if y == 0 or not prev_row[x]:
                    perimeter += 1
                if y == MAXC - 1 or not next_row[x]:
                    perimeter += 1

    out = [str(area)]
    if r == 2:
        out.append(str(perimeter))
    sys.stdout.write("\n".join(out) + "\n")

