public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Event implements Comparable<Event> {
        int x, y1, y2, delta;

        Event(int x, int y1, int y2, int delta) {
            this.x = x;
            this.y1 = y1;
            this.y2 = y2;
            this.delta = delta;
        }

        public int compareTo(Event o) {
            return Integer.compare(this.x, o.x);
        }
    }

    static class SegTree {
        int n;
        int[] cover;
        long[] len;
        int[] cnt;
        boolean[] leftCov, rightCov;
        int[] ys;

        SegTree(int[] ys) {
            this.ys = ys;
            this.n = ys.length - 1; // number of elementary intervals
            int size = Math.max(4 * n + 5, 10);
            cover = new int[size];
            len = new long[size];
            cnt = new int[size];
            leftCov = new boolean[size];
            rightCov = new boolean[size];
        }

        void pull(int idx, int l, int r) {
            if (cover[idx] > 0) {
                len[idx] = ys[r + 1] - ys[l];
                cnt[idx] = 1;
                leftCov[idx] = rightCov[idx] = true;
            } else if (l == r) {
                len[idx] = 0;
                cnt[idx] = 0;
                leftCov[idx] = rightCov[idx] = false;
            } else {
                int lc = idx << 1, rc = lc | 1;
                len[idx] = len[lc] + len[rc];
                cnt[idx] = cnt[lc] + cnt[rc] - (rightCov[lc] && leftCov[rc] ? 1 : 0);
                leftCov[idx] = leftCov[lc];
                rightCov[idx] = rightCov[rc];
            }
        }

        void update(int idx, int l, int r, int ql, int qr, int delta) {
            if (ql > r || qr < l || ql > qr) return;
            if (ql <= l && r <= qr) {
                cover[idx] += delta;
                pull(idx, l, r);
                return;
            }
            int mid = (l + r) >> 1;
            update(idx << 1, l, mid, ql, qr, delta);
            update(idx << 1 | 1, mid + 1, r, ql, qr, delta);
            pull(idx, l, r);
        }

        void update(int ql, int qr, int delta) {
            if (n <= 0 || ql > qr) return;
            update(1, 0, n - 1, ql, qr, delta);
        }

        long totalLen() {
            return n <= 0 ? 0 : len[1];
        }

        int segments() {
            return n <= 0 ? 0 : cnt[1];
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n;
        try {
            n = fs.nextInt();
        } catch (Exception e) {
            return;
        }
        int r = fs.nextInt();

        ArrayList<Event> events = new ArrayList<>(2 * n);
        int[] yAll = new int[2 * n];
        int yi = 0;

        for (int i = 0; i < n; i++) {
            int x1 = fs.nextInt();
            int y1 = fs.nextInt();
            int x2 = fs.nextInt();
            int y2 = fs.nextInt();
            if (x1 == x2 || y1 == y2) continue; // ignore degenerate rectangles
            if (x1 > x2) {
                int t = x1; x1 = x2; x2 = t;
            }
            if (y1 > y2) {
                int t = y1; y1 = y2; y2 = t;
            }
            events.add(new Event(x1, y1, y2, +1));
            events.add(new Event(x2, y1, y2, -1));
            yAll[yi++] = y1;
            yAll[yi++] = y2;
        }

        if (events.isEmpty()) {
            StringBuilder out = new StringBuilder();
            out.append(0).append('\n');
            if (r == 2) out.append(0).append('\n');
            System.out.print(out);
            return;
        }

        yAll = Arrays.copyOf(yAll, yi);
        Arrays.sort(yAll);
        int m = 0;
        for (int i = 0; i < yAll.length; i++) {
            if (i == 0 || yAll[i] != yAll[i - 1]) yAll[m++] = yAll[i];
        }
        int[] ys = Arrays.copyOf(yAll, m);

        Collections.sort(events);

        SegTree st = new SegTree(ys);

        long area = 0;
        long perimeter = 0;

        int i = 0;
        int prevX = events.get(0).x;

        while (i < events.size()) {
            int x = events.get(i).x;
            long dx = (long) x - prevX;
            long coveredLen = st.totalLen();
            int segs = st.segments();

            area += coveredLen * dx;
            if (r == 2) perimeter += 2L * segs * dx; // horizontal contribution

            long before = st.totalLen();

            while (i < events.size() && events.get(i).x == x) {
                Event e = events.get(i++);
                int l = Arrays.binarySearch(ys, e.y1);
                int rr = Arrays.binarySearch(ys, e.y2) - 1;
                st.update(l, rr, e.delta);
            }

            long after = st.totalLen();
            if (r == 2) perimeter += Math.abs(after - before); // vertical contribution at x

            prevX = x;
        }

        StringBuilder out = new StringBuilder();
        out.append(area).append('\n');
        if (r == 2) out.append(perimeter).append('\n');
        System.out.print(out);
    }
}

