int cmp(const void *a, const void *b) {
    Event *ea = (Event*)a;
    Event *eb = (Event*)b;
    if (ea->x != eb->x) return ea->x - eb->x;
    return eb->val - ea->val;
}

int ys[MAXC];
int ycnt;

int seg[4 * MAXC], cnt[4 * MAXC];
int len[4 * MAXC]; // total covered length in this segment
int cover[4 * MAXC]; // number of active covers
int lb[4 * MAXC], rb[4 * MAXC]; // leftmost and rightmost covered intervals for perimeter

void build(int idx, int l, int r) {
    seg[idx] = 0;
    cnt[idx] = 0;
    len[idx] = 0;
    cover[idx] = 0;
    lb[idx] = 0;
    rb[idx] = 0;
    if (l == r) return;
    int mid = (l + r) / 2;
    build(idx*2, l, mid);
    build(idx*2+1, mid+1, r);
}

void update(int idx, int l, int r, int ql, int qr, int val) {
    if (ql > r || qr < l) return;
    if (ql <= l && r <= qr) {
        cover[idx] += val;
    } else {
        int mid = (l + r) / 2;
        update(idx*2, l, mid, ql, qr, val);
        update(idx*2+1, mid+1, r, ql, qr, val);
    }
    if (cover[idx] > 0) {
        seg[idx] = ys[r+1] - ys[l];
        cnt[idx] = 1;
        len[idx] = ys[r+1] - ys[l];
        lb[idx] = 1;
        rb[idx] = 1;
    } else if (l == r) {
        seg[idx] = 0;
        cnt[idx] = 0;
        len[idx] = 0;
        lb[idx] = 0;
