                if (!cover[x][y]) continue;

                if (x == 0 || !cover[x - 1][y]) perimeter++;
                if (x == MAXC - 1 || !cover[x + 1][y]) perimeter++;
                if (y == 0 || !cover[x][y - 1]) perimeter++;
                if (y == MAXC - 1 || !cover[x][y + 1]) perimeter++;
            }
        }
    }

    printf("%lld\n", area);
    if (r == 2) printf("%lld\n", perimeter);

    return 0;
}
